sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float exposure;
uniform float contrast;
uniform float saturation;
uniform float temperature;
uniform float tint;
uniform float lift;
uniform float liftR;
uniform float liftG;
uniform float liftB;
uniform float gamma;
uniform float gammaR;
uniform float gammaG;
uniform float gammaB;
uniform float gain;
uniform float gainR;
uniform float gainG;
uniform float gainB;
uniform float curveY1;
uniform float curveY2;
uniform float curveY3;
uniform float curveR1;
uniform float curveR2;
uniform float curveR3;
uniform float curveG1;
uniform float curveG2;
uniform float curveG3;
uniform float curveB1;
uniform float curveB2;
uniform float curveB3;
uniform float vibrance;
uniform float shadows;
uniform float highlights;
uniform float blackPoint;
uniform float whitePoint;
uniform float gradeMix;
uniform float hslRedH;
uniform float hslRedS;
uniform float hslRedL;
uniform float hslYellowH;
uniform float hslYellowS;
uniform float hslYellowL;
uniform float hslGreenH;
uniform float hslGreenS;
uniform float hslGreenL;
uniform float hslCyanH;
uniform float hslCyanS;
uniform float hslCyanL;
uniform float hslBlueH;
uniform float hslBlueS;
uniform float hslBlueL;
uniform float hslMagentaH;
uniform float hslMagentaS;
uniform float hslMagentaL;

float cv(float x,float a,float b,float c){
 x=clamp(x,0.0,1.0)*4.0;
 if(x<1.0)return mix(0.0,a,x);
 if(x<2.0)return mix(a,b,x-1.0);
 if(x<3.0)return mix(b,c,x-2.0);
 return mix(c,1.0,x-3.0);
}

// studioGrade98: all new controls share the existing single texture pass.
float3 rgbHsl98(float3 c){
 float high=max(c.r,max(c.g,c.b)),low=min(c.r,min(c.g,c.b)),d=high-low;
 float l=(high+low)*0.5,h=0.0,s=0.0;
 if(d>0.00001){s=d/max(0.00001,1.0-abs(2.0*l-1.0));
  if(high==c.r)h=mod((c.g-c.b)/d,6.0);else if(high==c.g)h=(c.b-c.r)/d+2.0;else h=(c.r-c.g)/d+4.0;
  h=fract(h/6.0+1.0);
 }
 return float3(h,s,l);
}
float3 hslRgb98(float3 hsl){
 float3 hue=clamp(abs(mod(hsl.x*6.0+float3(0.0,4.0,2.0),6.0)-3.0)-1.0,0.0,1.0);
 return hsl.z+(hue-0.5)*(1.0-abs(2.0*hsl.z-1.0))*hsl.y;
}
float hueBand98(float hue,float center){float d=abs(hue-center);d=min(d,1.0-d);return 1.0-smoothstep(0.0,1.0/6.0,d);}

half4 main(float2 coord){
 float4 src=float4(image.eval(coord));
 float3 rgb=src.a>0.00001?src.rgb/src.a:float3(0.0);
 rgb*=exp2(exposure);
 rgb*=exp2(float3(temperature*0.35-tint*0.12,tint*0.24,-temperature*0.35-tint*0.12));
 float3 lo=float3(lift*0.25)+float3(liftR,liftG,liftB)*0.25;
 float3 ga=exp2(float3(gamma)+float3(gammaR,gammaG,gammaB));
 float3 hi=exp2(float3(gain)+float3(gainR,gainG,gainB));
 rgb=max(float3(0.0),rgb+(float3(1.0)-rgb)*lo);
 rgb=pow(rgb,float3(1.0)/ga)*hi;
 rgb=(rgb-float3(0.5))*contrast+float3(0.5);
 float lum=dot(rgb,float3(0.2126,0.7152,0.0722));
 rgb=mix(float3(lum),rgb,saturation);
 rgb=float3(cv(rgb.r,curveY1,curveY2,curveY3),cv(rgb.g,curveY1,curveY2,curveY3),cv(rgb.b,curveY1,curveY2,curveY3));
 rgb=float3(cv(rgb.r,curveR1,curveR2,curveR3),cv(rgb.g,curveG1,curveG2,curveG3),cv(rgb.b,curveB1,curveB2,curveB3));

 if(abs(shadows)+abs(highlights)+abs(blackPoint)+abs(whitePoint-1.0)>0.000001){
  float toneLum=clamp(dot(rgb,float3(0.2126,0.7152,0.0722)),0.0,1.0);
  float shadowMask=1.0-smoothstep(0.12,0.62,toneLum),highlightMask=smoothstep(0.38,0.9,toneLum);
  rgb*=exp2((shadows*shadowMask+highlights*highlightMask)*1.5);
  rgb=(rgb-float3(blackPoint))/max(0.01,whitePoint-blackPoint);
 }
 if(abs(hslRedH) + abs(hslRedS) + abs(hslRedL) + abs(hslYellowH) + abs(hslYellowS) + abs(hslYellowL) + abs(hslGreenH) + abs(hslGreenS) + abs(hslGreenL) + abs(hslCyanH) + abs(hslCyanS) + abs(hslCyanL) + abs(hslBlueH) + abs(hslBlueS) + abs(hslBlueL) + abs(hslMagentaH) + abs(hslMagentaS) + abs(hslMagentaL)>0.000001){
  float3 hsl=rgbHsl98(clamp(rgb,0.0,1.0)),delta=float3(0.0);
  float chroma=smoothstep(0.01,0.08,hsl.y);
  delta+=hueBand98(hsl.x,0.0/6.0)*float3(hslRedH,hslRedS,hslRedL);
  delta+=hueBand98(hsl.x,1.0/6.0)*float3(hslYellowH,hslYellowS,hslYellowL);
  delta+=hueBand98(hsl.x,2.0/6.0)*float3(hslGreenH,hslGreenS,hslGreenL);
  delta+=hueBand98(hsl.x,3.0/6.0)*float3(hslCyanH,hslCyanS,hslCyanL);
  delta+=hueBand98(hsl.x,4.0/6.0)*float3(hslBlueH,hslBlueS,hslBlueL);
  delta+=hueBand98(hsl.x,5.0/6.0)*float3(hslMagentaH,hslMagentaS,hslMagentaL);
  hsl.x=fract(hsl.x+delta.x*chroma/360.0+1.0);
  hsl.y=clamp(hsl.y*(1.0+delta.y*chroma),0.0,1.0);
  hsl.z=clamp(hsl.z+delta.z*chroma,0.0,1.0);
  rgb=hslRgb98(hsl);
 }
 if(abs(vibrance)>0.000001){
  float high=max(rgb.r,max(rgb.g,rgb.b)),low=min(rgb.r,min(rgb.g,rgb.b));
  float sat=high>0.00001?(high-low)/high:0.0;
  float factor=1.0+vibrance*(vibrance>0.0?1.0-sat:1.0);
  float y=dot(rgb,float3(0.2126,0.7152,0.0722));rgb=mix(float3(y),rgb,factor);
 }
 return float4(mix(src.rgb,clamp(rgb,0.0,1.0)*src.a,gradeMix),src.a);

}
